<?php $activePage='scan';$pageTitle='Resume scan · ResumeIQ';$searchPlaceholder='Search the recruiter workspace';$pageStyles='<style>.scan-grid{display:grid;grid-template-columns:280px minmax(0,1fr) 150px;gap:10px;margin-top:12px;padding:14px}.filebox{min-height:108px;border:1px dashed #d8d2ee;border-radius:14px;background:#faf9ff;display:flex;align-items:center;gap:12px;padding:15px;position:relative}.filebox input{position:absolute;inset:0;opacity:0;cursor:pointer}.upload-icon{width:42px;height:42px;border-radius:12px;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center;font-size:16px}.filebox strong{display:block;font-size:11px}.filebox span span{display:block;color:var(--muted);font-size:9px;margin-top:4px}.jd{position:relative}.jd label{position:absolute;top:9px;left:12px;color:var(--muted);font-size:9px;text-transform:uppercase;font-weight:700;z-index:2}.jd textarea{height:108px;padding-top:28px}.scan-actions{display:flex;flex-direction:column;gap:8px}.scan-actions .btn-primary{flex:1}.flow{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:10px}.flow-item{padding:14px;display:flex;align-items:center;gap:10px}.flow-item i{width:34px;height:34px;border-radius:11px;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center}.flow-item b{display:block;font-size:10px}.flow-item span{color:var(--muted);font-size:9px}.result-grid{display:grid;grid-template-columns:260px 1fr;gap:10px;margin-top:12px}.score-card{padding:19px;text-align:center}.ring{--score:0;width:118px;height:118px;margin:auto;background:conic-gradient(var(--primary) calc(var(--score)*1%),#edeaf7 0);clip-path:circle(50%);position:relative;display:grid;place-items:center}.ring:before{content:"";position:absolute;inset:10px;background:#fff;clip-path:circle(50%)}.ring strong{position:relative;font-size:25px}.metric-row{display:flex;justify-content:space-between;padding:9px 0;border-top:1px solid var(--line);font-size:10px}.analysis{padding:20px}.analysis h2{margin:0;font-size:21px}.analysis p{color:var(--muted);font-size:10px}.spectrum{margin:35px 0 18px;position:relative}.spectrum-track{height:9px;border-radius:9px;background:linear-gradient(90deg,#ef8294,#ecc263,#6f45ff,#18a66f)}.spectrum-mark{position:absolute;top:-28px;transform:translateX(-50%);padding:4px 7px;border-radius:7px;background:var(--text);color:#fff;font-size:9px}.keyword-grid,.experience-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.subpanel{border:1px solid var(--line);border-radius:14px;padding:14px}.subpanel h3,.section h2{font-size:10px;text-transform:uppercase;letter-spacing:.08em;margin:0 0 10px}.pills{display:flex;flex-wrap:wrap;gap:5px}.pill{padding:4px 7px;border-radius:7px;background:var(--green-soft);color:var(--green);font-size:9px}.pill.miss{background:#fff1f3;color:var(--danger)}.section{margin-top:10px;padding:18px}.meta{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}.meta span{display:block;color:var(--muted);font-size:8px;text-transform:uppercase}.meta strong{display:block;font-size:10px;margin-top:3px;overflow:hidden;text-overflow:ellipsis}.job{padding:9px 0;border-bottom:1px solid var(--line)}.job strong{font-size:10px}.job span{display:block;color:var(--muted);font-size:9px;margin-top:3px}.gap-note{padding:8px;border-radius:8px;background:var(--amber-soft);color:var(--amber);font-size:9px;margin-bottom:5px}.raw{max-height:220px;overflow:auto;white-space:pre-wrap;background:#fafafe;border:1px solid var(--line);border-radius:12px;padding:12px;font:9px/1.65 monospace}@media(max-width:900px){.scan-grid{grid-template-columns:1fr}.scan-actions{flex-direction:row}.result-grid{grid-template-columns:1fr}.meta{grid-template-columns:repeat(3,1fr)}}@media(max-width:560px){.flow,.keyword-grid,.experience-grid{grid-template-columns:1fr}.meta{grid-template-columns:1fr 1fr}}</style>';require __DIR__.'/partials/header.php';?>
