$result['text_length'])?></strong></div></div></section><section class="panel section"><h2>Experience intelligence</h2><div class="experience-grid"><div><?php if(!$result['experience']['jobs']):?><p>No reliable dated roles found.</p><?php endif?><?php foreach($result['experience']['jobs'] as $job):?><div class="job"><strong><?=htmlspecialchars($job['start'].' — '.$job['end'])?></strong><span><?=round($job['months']/12,1)?> years · <?=htmlspecialchars(implode(', ',$job['skills'])?:'No mapped skills')?></span></div><?php endforeach?></div><div><h2>Skill tenure estimate</h2><div class="pills"><?php foreach($result['experience']['skill_months'] as $skill=>$months):?><span class="pill"><?=htmlspecialchars($skill)?> · <?=round($months/12,1)?>y</span><?php endforeach?></div><h2 style="margin-top:16px">Employment gaps</h2><?php if(!$result['experience']['gaps']):?><p>No gap of 2+ months detected.</p><?php endif?><?php foreach($result['experience']['gaps'] as $gap):?><div class="gap-note"><?=$gap['months']?> months · <?=htmlspecialchars($gap['after'].' to '.$gap['before'])?></div><?php endforeach?></div></div></section><section class="panel section"><h2>Extracted text</h2><div class="raw"><?=htmlspecialchars($result['extracted_text'])?></div></section><?php endif?>
